import pandas as pd

def clean(df):
    df = pd.read_csv("in.csv")
    df[df["amount"] < 0]["amount"] = 0          # clamp negatives
    df["country"] = df["country"].astype("object")
    for i in range(len(df)):
        df.loc[i, "label"] = df.loc[i, "sku"].upper()
    df["ts"] = pd.to_datetime(df["ts"])
    return df.append({"sku": "TOTAL"}, ignore_index=True)
